From 7f063724e8d049a0070fb05ff6028326761198f9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:36:01 +0100
Subject: [PATCH] applets/timer: vertically center the digits in the desktop
 widget

The digits row took the full height of its layout cell but only drew its
digits at the top, so a widget taller than the digits left all its empty
space below them. Wrap the row in an item and center it vertically there.

BUG: 459475
---
 applets/timer/TimerView.qml | 68 ++++++++++++++++++++-----------------
 1 file changed, 37 insertions(+), 31 deletions(-)

diff --git a/applets/timer/TimerView.qml b/applets/timer/TimerView.qml
index dc1f94e40..0c0375a33 100644
--- a/applets/timer/TimerView.qml
+++ b/applets/timer/TimerView.qml
@@ -83,42 +83,48 @@ MouseArea {
             sourceComponent: fullRepresentation.inPanel ? popupHeadingComponent : desktopHeadingComponent
         }

-        TimerEdit {
-            id: timerDigits
-
+        Item {
             Layout.fillWidth: true
             Layout.fillHeight: true
             Layout.verticalStretchFactor: 3
+            implicitHeight: timerDigits.implicitHeight
             visible: Plasmoid.configuration.showRemainingTime

-            value: fullRepresentation.seconds
-            editable: !fullRepresentation.running
-            alertMode: fullRepresentation.alertMode
-            showSeconds: Plasmoid.configuration.showSeconds
-            onDigitModified: valueDelta => fullRepresentation.adjustTimerRequested(valueDelta)
-            onToggleTimerRequested: fullRepresentation.toggleTimerRequested()
-            maximumHeight: height
-            SequentialAnimation on opacity {
-                running: fullRepresentation.suspended;
-                loops: Animation.Infinite;
-                onRunningChanged: if (!running) { timerDigits.opacity = 1.0 }
-                NumberAnimation {
-                    duration: Kirigami.Units.veryLongDuration * 2;
-                    from: 1.0;
-                    to: 0.2;
-                    easing.type: Easing.InOutQuad;
-                }
-                PauseAnimation {
-                    duration: Kirigami.Units.veryLongDuration;
-                }
-                NumberAnimation {
-                    duration: Kirigami.Units.veryLongDuration * 2;
-                    from: 0.2;
-                    to: 1.0;
-                    easing.type: Easing.InOutQuad;
-                }
-                PauseAnimation {
-                    duration: Kirigami.Units.veryLongDuration;
+            TimerEdit {
+                id: timerDigits
+
+                anchors.verticalCenter: parent.verticalCenter
+                width: parent.width
+
+                value: fullRepresentation.seconds
+                editable: !fullRepresentation.running
+                alertMode: fullRepresentation.alertMode
+                showSeconds: Plasmoid.configuration.showSeconds
+                onDigitModified: valueDelta => fullRepresentation.adjustTimerRequested(valueDelta)
+                onToggleTimerRequested: fullRepresentation.toggleTimerRequested()
+                maximumHeight: parent.height
+                SequentialAnimation on opacity {
+                    running: fullRepresentation.suspended;
+                    loops: Animation.Infinite;
+                    onRunningChanged: if (!running) { timerDigits.opacity = 1.0 }
+                    NumberAnimation {
+                        duration: Kirigami.Units.veryLongDuration * 2;
+                        from: 1.0;
+                        to: 0.2;
+                        easing.type: Easing.InOutQuad;
+                    }
+                    PauseAnimation {
+                        duration: Kirigami.Units.veryLongDuration;
+                    }
+                    NumberAnimation {
+                        duration: Kirigami.Units.veryLongDuration * 2;
+                        from: 0.2;
+                        to: 1.0;
+                        easing.type: Easing.InOutQuad;
+                    }
+                    PauseAnimation {
+                        duration: Kirigami.Units.veryLongDuration;
+                    }
                 }
             }
         }
-- 
